-- pgTAP da S4 do admin (docs/sql/20261015_admin_s4_permissao_dados.sql, Decisão 163): o banco exige a permissão da tela
-- nas tabelas de dado pessoal e no resto. Só em banco descartável: baseline + docs/sql até o estado de produção + SQL da S3
-- + o da S4, e rodar este arquivo (psql -f ou `supabase test db`). Tudo em begin ... rollback. Nunca contra produção.
-- Gerado por script a partir da tabela "tabela -> permissões que leem" (1 = lê a linha semeada, 0 = não).
-- pg_temp.como() troca papel e claims do JWT como o PostgREST; pg_temp.n(sql) = primeira coluna bigint do select;
-- pg_temp.upd(sql) = linhas afetadas por update/delete (RLS que esconde a linha dá 0, sem erro).
-- Contas: adm_<permissão> (aal2, fator verificado), super, adm_none (admin sem permissão), adm_aal1 (todas as permissões,
-- token aal1), p1 (dono dos eventos), p2 (outro produtor), comprador (ingresso ativo no evento de p1), comum.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(538);

create function pg_temp.como(p_role text, p uuid default null, p_aal text default 'aal1') returns void
language plpgsql as $f$
begin
  perform set_config('request.jwt.claims', case when p_role = 'postgres' then '' else json_strip_nulls(json_build_object(
    'role', p_role, 'sub', p, 'aal', case when p is not null then p_aal end))::text end, true);
  perform set_config('role', case when p_role = 'postgres' then 'none' else p_role end, true);
end $f$;
create function pg_temp.n(p text) returns bigint language plpgsql as $f$
declare r bigint; begin execute p into r; return r; end $f$;
create function pg_temp.upd(p text) returns bigint language plpgsql as $f$
declare r bigint; begin execute p; get diagnostics r = row_count; return r; end $f$;
grant execute on function pg_temp.como(text, uuid, text), pg_temp.n(text), pg_temp.upd(text) to anon, authenticated, service_role;
grant execute on all functions in schema extensions to anon, authenticated, service_role;

